<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import AppDialog from './AppDialog.vue';
import MonitoringAgendas from './MonitoringAgendas.vue';
import CollectionRequest from './CollectionRequest.vue';
import MonitoringLimits from './MonitoringLimits.vue';
import {createCancelablePolling} from '../services/polling';
type Execution={id:number;solicitada_por:number|null;monitoramento_id:string|null;status:string;iniciada_em:string;concluida_em:string|null;cancelamento_solicitado:boolean;cancelavel?:boolean;recuperavel?:boolean;limite_duracao_excedido:boolean;limite_volume_excedido:boolean};
const props=defineProps<{canEdit?:boolean;canManage?:boolean;request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const created=ref<number|null>(null);
function requested(id:number){created.value=id;filter.value='';void polling.refresh();}
const rows=ref<Execution[]>([]),busy=ref(false),error=ref(''),loaded=ref(false),automatic=ref(true),updated=ref(''),selected=ref<number|null>(null),filter=ref('');
const labels:Record<string,string>={solicitada:'Solicitada',executando:'Executando',concluida:'Concluída',falhou:'Falhou',cancelada:'Cancelada'};
const visible=computed(()=>rows.value.filter(row=>!filter.value||row.status===filter.value));
const detail=computed(()=>rows.value.find(row=>row.id===selected.value));
const cancelling=ref(false),confirmCancel=ref(false),cancelError=ref(''),cancelNotice=ref('');
const recovering=ref(false),confirmRecovery=ref(false),recoveryJustification=ref(''),recoveryError=ref(''),recoveryNotice=ref('');
let alive=true;
function refreshState(){polling.pause();if(automatic.value)polling.resume();else void polling.refresh();}
async function cancel(){if(!props.canEdit||!detail.value?.cancelavel||!confirmCancel.value||cancelling.value)return;const id=detail.value.id;cancelling.value=true;cancelError.value='';cancelNotice.value='';try{await props.request('/api/contexto/execucoes/'+id+'/cancelar','POST',{});if(!alive)return;confirmCancel.value=false;cancelNotice.value='Pedido de cancelamento registrado. Aguarde a situação confirmada pelo servidor.';}catch(cause){if(alive)cancelError.value=(cause as Error).message;}finally{if(alive){cancelling.value=false;polling.pause();if(automatic.value)polling.resume();else void polling.refresh();}}}
async function recover(){if(!props.canManage||!detail.value?.recuperavel||!confirmRecovery.value||recoveryJustification.value.trim().length<8||recovering.value)return;const id=detail.value.id;recovering.value=true;recoveryError.value='';recoveryNotice.value='';try{await props.request('/api/contexto/execucoes/'+id+'/recuperar','POST',{justificativa:recoveryJustification.value.trim(),consumidor_encerrado:true});if(!alive)return;confirmRecovery.value=false;recoveryJustification.value='';recoveryNotice.value='Recuperação registrada. A reserva anterior foi invalidada e a execução foi marcada como falhou.';}catch(cause){if(alive)recoveryError.value=(cause as Error).message;}finally{if(alive){recovering.value=false;refreshState();}}}
function date(value:string|null){if(!value)return 'Ainda não encerrada';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'Data indisponível':parsed.toLocaleString('pt-BR');}
const polling=createCancelablePolling({load:signal=>props.request<Execution[]>('/api/contexto/execucoes','GET',undefined,signal),data:value=>{rows.value=value;loaded.value=true;error.value='';updated.value=new Date().toLocaleTimeString('pt-BR');},error:cause=>{error.value=(cause as Error).message||'Não foi possível consultar as execuções.';},busy:value=>{busy.value=value;}});
function toggle(){automatic.value=!automatic.value;if(automatic.value)polling.resume();else polling.pause();}
onMounted(()=>{void polling.refresh();});
onBeforeUnmount(()=>{alive=false;polling.stop();});
</script>
<template><section class="registry-panel" aria-label="Execuções de monitoramento">
  <header class="registry-heading"><div><span class="eyebrow">Histórico do escritório</span><h2>Execuções de monitoramento</h2><p>Acompanhe as últimas 100 execuções das consultas sindicais deste escritório.</p></div><div class="monitoring-actions"><button type="button" class="secondary" :disabled="busy" @click="polling.refresh">Atualizar execuções</button><button type="button" class="secondary" :aria-pressed="!automatic" @click="toggle">{{ automatic?'Pausar atualização':'Retomar atualização' }}</button></div></header>
  <MonitoringAgendas :can-manage="!!canManage" :request="request" />
  <MonitoringLimits :can-manage="!!canManage" :request="request" />
  <CollectionRequest v-if="canEdit" :request="request" @created="requested" />
  <p v-if="created!==null" role="status">Execução #{{ created }} solicitada. Acompanhe sua situação no histórico.</p>
  <p role="status">{{ busy?'Consultando execuções…':automatic?'Atualização automática a cada 10 segundos.':'Atualização automática pausada.' }}<span v-if="updated"> Última consulta: {{ updated }}.</span></p>
  <div v-if="error" role="alert"><p>{{ error }}</p><p>{{ loaded?'Os dados exibidos são da última consulta bem-sucedida.':'Nenhuma consulta concluída.' }} {{ automatic?'Uma nova tentativa ocorrerá automaticamente.':'Retome a atualização ou tente novamente.' }}</p><button type="button" class="secondary" :disabled="busy" @click="polling.refresh">Tentar novamente</button></div>
  <label>Situação da execução<select v-model="filter"><option value="">Todas as situações</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label>
  <p v-if="loaded">{{ visible.length }} de {{ rows.length }} execuções nesta consulta.</p>
  <div v-if="loaded" class="registry-scroll"><table><caption>Histórico de execuções</caption><thead><tr><th scope="col">Execução</th><th scope="col">Consulta</th><th scope="col">Situação</th><th scope="col">Registrada em</th><th scope="col">Detalhe</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id"><td>#{{ item.id }}</td><td>{{ item.monitoramento_id?'Consulta #'+item.monitoramento_id:'Consulta indisponível' }}</td><td><span class="status-badge" :data-tone="item.status==='concluida'?'success':item.status==='falhou'?'danger':'neutral'">{{ labels[item.status]||item.status }}</span><p v-if="item.cancelamento_solicitado">Cancelamento solicitado</p><p v-if="item.limite_duracao_excedido||item.limite_volume_excedido">Limite excedido</p></td><td>{{ date(item.iniciada_em) }}</td><td><button type="button" class="secondary" :aria-label="'Ver execução '+item.id" @click="selected=item.id;confirmCancel=false;cancelError='';cancelNotice='';confirmRecovery=false;recoveryJustification='';recoveryError='';recoveryNotice=''">Ver detalhe</button></td></tr><tr v-if="!visible.length"><td colspan="5">{{ rows.length?'Nenhuma execução corresponde à situação selecionada.':'Ainda não há execuções neste escritório.' }}</td></tr></tbody></table></div>
</section>
<AppDialog v-if="selected!==null" title="Detalhes da execução" :busy="cancelling||recovering" @close="selected=null"><p v-if="error" role="alert">Consulta indisponível. Este detalhe corresponde à última consulta bem-sucedida.</p><template v-if="detail"><h3>Execução #{{ detail.id }}</h3><dl class="monitoring-detail"><dt>Situação</dt><dd>{{ labels[detail.status]||detail.status }}</dd><dt>Consulta sindical</dt><dd>{{ detail.monitoramento_id?'#'+detail.monitoramento_id:'Indisponível' }}</dd><dt>Solicitante</dt><dd>{{ detail.solicitada_por?'Usuário #'+detail.solicitada_por:'Não informado' }}</dd><dt>Registrada em</dt><dd>{{ date(detail.iniciada_em) }}</dd><dt>Encerrada em</dt><dd>{{ date(detail.concluida_em) }}</dd><dt>Cancelamento solicitado</dt><dd>{{ detail.cancelamento_solicitado?'Sim; confira a situação atual da execução.':'Não' }}</dd><dt>Limite de duração excedido</dt><dd>{{ detail.limite_duracao_excedido?'Sim':'Não' }}</dd><dt>Limite de volume excedido</dt><dd>{{ detail.limite_volume_excedido?'Sim':'Não' }}</dd></dl><p v-if="cancelNotice" role="status">{{ cancelNotice }}</p><p v-if="cancelError" role="alert">{{ cancelError }} A situação foi consultada novamente; confira antes de repetir.</p><p v-if="recoveryNotice" role="status">{{ recoveryNotice }}</p><p v-if="recoveryError" role="alert">{{ recoveryError }} A situação foi consultada novamente; confira antes de tentar outra recuperação.</p><form v-if="canEdit&&detail.cancelavel" @submit.prevent="cancel"><p>Uma solicitação em fila pode ser encerrada imediatamente. Durante a execução, o worker precisa reconhecer o pedido e encerrar o trabalho.</p><label class="confirmation-check"><input v-model="confirmCancel" type="checkbox" :disabled="cancelling||recovering">Confirmo o pedido de cancelamento desta execução</label><button class="danger" type="submit" :disabled="cancelling||recovering||!confirmCancel">{{ cancelling?'Solicitando…':'Solicitar cancelamento' }}</button></form><form v-if="canManage&&detail.recuperavel" class="recovery-form" @submit.prevent="recover"><h4>Recuperar execução interrompida</h4><p>Use somente após confirmar que o consumidor anterior encerrou. A recuperação não repete a coleta: invalida a reserva antiga, marca a execução como falhou e registra a justificativa.</p><label>Justificativa da recuperação<textarea v-model="recoveryJustification" :disabled="cancelling||recovering" minlength="8" maxlength="1000" required></textarea></label><p v-if="recoveryJustification.trim()&&recoveryJustification.trim().length<8" role="alert">Informe ao menos 8 caracteres na justificativa.</p><label class="confirmation-check"><input v-model="confirmRecovery" type="checkbox" :disabled="cancelling||recovering">Confirmo que o consumidor anterior foi encerrado</label><button class="danger" type="submit" :disabled="cancelling||recovering||!confirmRecovery||recoveryJustification.trim().length<8">{{ recovering?'Recuperando…':'Confirmar recuperação' }}</button></form></template><p v-else>Esta execução não está mais entre as últimas 100 retornadas pela consulta. Feche o detalhe para conferir o histórico atual.</p></AppDialog>
</template>
<style scoped>
.registry-heading,.monitoring-actions{display:flex;gap:var(--space-3,12px);flex-wrap:wrap;align-items:center;justify-content:space-between}.monitoring-detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.monitoring-detail dd{margin:0;overflow-wrap:anywhere}.monitoring-detail dt{font-weight:600}.recovery-form{display:grid;gap:12px;margin-top:20px}.recovery-form p{margin:0}.recovery-form label{display:grid;gap:6px}.recovery-form label.confirmation-check{display:flex}.recovery-form textarea{min-height:90px;resize:vertical}@media(max-width:560px){.monitoring-detail{grid-template-columns:1fr;gap:6px}.monitoring-detail dd{margin-bottom:12px}}
</style>
